import hashlib
import json


def fingerprint(cert_der: bytes) -> str:
    """Compute SHA-256 fingerprint of DER-encoded certificate."""
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    """Stores pinned certificate fingerprints for hosts."""

    def __init__(self, pins: dict = None):
        self._pins = pins or {}

    @classmethod
    def load(cls):
        """Load the pin store with built-in pinned certificates."""
        import pkgutil
        import json

        # Load pin data from bundled data file
        data = pkgutil.get_data(__name__, "pins.json")
        if data:
            pins = json.loads(data)
        else:
